contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address tokenAddr,
        uint256 tokenAmount,
        address from,
        address to,
        address operator,
        address[] memory whitelist,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory floorTokens,
        C.ERC20Asset[] memory erc20Assets,
        C.ERC721Asset[] memory erc721Assets
    ) public payable {
        if (c.owner() != address(this)) {
            c.transferOwnership(address(this));
        }

        if (c.baseURI().length == 0) {
            c.setBaseURI("ipfs://");
        }
        if (c.fee() != 0) {
            c.setFee(0);
        }

        c.setApprovalForAll(from, true);
        c.approve(address(this), uint256(keccak256(abi.encode(orderHash)))));

        C.Order memory order;
        order.maker = address(this);
        order.isCall = false;
        order.isLong = false;
        order.baseAsset = baseAsset;
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = whitelist;
        order.floorTokens = floorTokens;
        order.erc20Assets = erc20Assets;
        order.erc721Assets = erc721Assets;

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeOrderHash = c.hashOppositeOrder(order);
        uint256 positionId = uint256(oppositeOrderHash);

        uint256[] memory floorAssetTokenIds = new uint256[](0);

        c.setBaseURI("ipfs://");
        c.setFee(0);

        c.fillOrder(order, "", floorAssetTokenIds);

        assert(c.ownerOf(uint256(orderHash)) == address(this));
        assert(c.ownerOf(positionId) == address(this));
    }

    receive() external payable {}
}

