contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens,
        C.ERC20Asset[] memory erc20Assets,
        C.ERC721Asset[] memory erc721Assets,
        bytes memory signature,
        uint256[] memory floorAssetTokenIds
    ) public payable {
        require(address(this).balance >= premium, "insufficient balance for test");
        require(expiration > block.timestamp, "expiration must be in future");
        require(duration <= 10_000 days, "duration too long");

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        bytes32 expectedPositionHash = c.hashOppositeOrder(order);
        uint256 expectedPositionId = uint256(expectedPositionHash);
        uint256 orderPositionId = uint256(orderHash);

        require(c.ownerOf(orderPositionId) == address(0), "order position already minted");
        require(c.ownerOf(expectedPositionId) == address(0), "opposite position already minted");

        uint256 returnedPositionId;
        bool reverted;
        try c.fillOrder{value: msg.value}(order, signature, floorAssetTokenIds) returns (uint256 positionId) {
            returnedPositionId = positionId;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(
                returnedPositionId == expectedPositionId &&
                c.ownerOf(orderPositionId) == maker &&
                c.ownerOf(expectedPositionId) == address(this)
            );
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

