contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens,
        uint256[] memory floorAssetTokenIds
    ) public {
        require(maker != address(0), "maker zero");
        require(baseAsset.code.length > 0, "baseAsset not contract");
        require(duration < 10_000 days, "duration too long");
        require(block.timestamp < expiration, "order expired");
        require(whitelist.length == 0, "whitelist not empty for test simplicity");
        require(isCall && isLong ? floorAssetTokenIds.length == floorTokens.length : floorAssetTokenIds.length == 0, "bad floor token ids");

        C.Order memory order;
        order.maker = maker;
        order.isCall = isCall;
        order.isLong = isLong;
        order.baseAsset = baseAsset;
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = whitelist;
        order.floorTokens = floorTokens;
        order.erc20Assets = new C.ERC20Asset[](0);
        order.erc721Assets = new C.ERC721Asset[](0);

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);

        // Verify the hashes are distinct before filling (precondition for the rule).
        require(orderHash != oppositeHash, "hashes must be distinct");

        bool filled;
        try c.fillOrder(order, new bytes(0), floorAssetTokenIds) returns (uint256 positionId) {
            filled = true;
            uint256 filledLongId = uint256(orderHash);
            uint256 filledShortId = uint256(oppositeHash);
            assert(
                positionId == filledShortId &&
                c.ownerOf(filledLongId) == maker &&
                c.ownerOf(filledShortId) == address(this) &&
                filledLongId != filledShortId
            );
        } catch {
            assert(!filled);
        }
    }

    receive() external payable {}
}

