        require(duration < 10_000 days);
        require(expiration > block.timestamp);
        require(msg.value == 0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: true,
            isLong: true,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
