        });

        bytes memory signature = new bytes(0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeOrderHash = c.hashOppositeOrder(order);
        uint256 positionId = uint256(oppositeOrderHash);
        uint256 orderTokenId = uint256(orderHash);

        bool reverted;
        try c.fillOrder(order, signature, floorAssetTokenIds) returns (uint256 returnedPositionId) {
            reverted = false;
            positionId = returnedPositionId;
        } catch {
